begin;
select plan(28);
select has_function('public','create_flashing_takeoff_draft','atomic flashing takeoff RPC exists');

set local role postgres;
insert into public.organizations(id,name) values('00000000-0000-4000-8000-000000000011','DEMO other organization flashing transfer');
insert into public.organization_members(organization_id,user_id,role) values('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000002','owner');
insert into public.projects(id,organization_id,name,project_type,status,created_by) values
 ('00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000010','DEMO flashing transfer project','roof_renovation','draft','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000992','00000000-0000-4000-8000-000000000010','DEMO other flashing project','roof_renovation','draft','00000000-0000-4000-8000-000000000001');
insert into public.calculations(id,organization_id,project_id,calculator_type,display_name,status) values
 ('00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','sheet_metal.flashings.material-estimate','DEMO flashing','current'),
 ('00000000-0000-4000-8000-000000002001','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000992','sheet_metal.flashings.material-estimate','DEMO flashing unresolved','current');
insert into public.calculation_revisions(id,organization_id,calculation_id,revision_number,input_schema_version,calculator_implementation_version,input_snapshot,output_snapshot,data_provenance,validation_status,warnings,created_by) values
 ('00000000-0000-4000-8000-000000000994','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000993',1,'1.0.0','1.0.0',
  '{"sectionSpec":{"nominalLengthMm":2000},"runs":[{"id":"run-a","category":"verge","name":"DEMO orom","lengthMm":3900,"startExtensionMm":100,"endExtensionMm":0,"reserveMm":100}],"manualComponents":[{"id":"clip","category":"custom","name":"DEMO kapocs","quantity":2}]}'::jsonb,
  '{"runs":[{"id":"run-a","category":"verge","name":"DEMO orom","lengthMm":3900,"requiredCoverageLengthMm":4000,"reserveMm":100,"planningTargetLengthMm":4100,"nominalSectionLengthMm":2000,"estimatedSectionCount":3,"jointCount":2,"totalNominalStockLengthMm":6000}],"manualComponents":[{"id":"clip","category":"custom","name":"DEMO kapocs","quantity":2}],"warnings":[]}'::jsonb,
  '{"test":"DEMO F9.6.2.3"}'::jsonb,'verified','[]'::jsonb,'00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000002002','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000002001',1,'1.0.0','1.0.0',
  '{"sectionSpec":{"nominalLengthMm":2000},"runs":[{"id":"run-a","category":"verge","name":"DEMO unresolved","lengthMm":3900,"startExtensionMm":0,"endExtensionMm":0,"reserveMm":100}],"manualComponents":[]}'::jsonb,
  '{"runs":[{"id":"run-a","category":"verge","name":"DEMO unresolved","lengthMm":3900,"requiredCoverageLengthMm":3900,"reserveMm":100,"planningTargetLengthMm":4000,"nominalSectionLengthMm":2000,"estimatedSectionCount":null,"jointCount":null,"totalNominalStockLengthMm":null}],"manualComponents":[],"warnings":[]}'::jsonb,
  '{"test":"DEMO F9.6.2.3 unresolved"}'::jsonb,'verified','[]'::jsonb,'00000000-0000-4000-8000-000000000001');
update public.calculations set current_revision_id='00000000-0000-4000-8000-000000000994' where id='00000000-0000-4000-8000-000000000993';
update public.calculations set current_revision_id='00000000-0000-4000-8000-000000002002' where id='00000000-0000-4000-8000-000000002001';
insert into public.material_products(id,organization_id,category,name,status,data_provenance,created_by) values
 ('00000000-0000-4000-8000-000000000995','00000000-0000-4000-8000-000000000010','flashing','DEMO flashing catalog','active','demo','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000996','00000000-0000-4000-8000-000000000010','gutter','DEMO wrong category','active','demo','00000000-0000-4000-8000-000000000001');
insert into public.material_products(id,organization_id,category,name,status,data_provenance,created_by) values
 ('00000000-0000-4000-8000-000000001009','00000000-0000-4000-8000-000000000011','flashing','DEMO foreign flashing','active','demo','00000000-0000-4000-8000-000000000002');
insert into public.material_variants(id,organization_id,product_id,name,purchasing_unit,length_mm,technical_specs,data_provenance,source_name,created_by) values
 ('00000000-0000-4000-8000-000000000997','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000995','DEMO piece','piece',2000,'{"source":"DEMO"}','demo','DEMO catalog','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000998','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000995','DEMO linear meter','linear_meter',null,'{"source":"DEMO"}','demo','DEMO catalog','00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000999','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000996','DEMO wrong category piece','piece',2000,'{}','demo','DEMO catalog','00000000-0000-4000-8000-000000000001');
insert into public.material_variants(id,organization_id,product_id,name,purchasing_unit,data_provenance,created_by)
values('00000000-0000-4000-8000-000000000981','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000001009','DEMO foreign piece','piece','demo','00000000-0000-4000-8000-000000000002');
insert into public.material_prices(id,organization_id,variant_id,amount,purchasing_unit,price_kind,price_source,effective_date,data_provenance,source_name,created_by)
values('00000000-0000-4000-8000-000000001000','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000998',123,'linear_meter','net','DEMO','2026-10-13','demo','DEMO árforrás','00000000-0000-4000-8000-000000000001');

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select lives_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','DEMO flashing draft','00000000-0000-4000-8000-000000001001','[{"candidateId":"run-linear:run-a","variantId":"00000000-0000-4000-8000-000000000998"},{"candidateId":"manual:clip","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'authorized transfer creates one draft');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001'),1,'one idempotent draft exists');
select results_eq($$select final_quantity::numeric,quantity_unit::text from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') order by quantity_unit$$,$$values (4.1::numeric,'linear_meter'::text),(2::numeric,'piece'::text)$$,'saved server quantities and explicit units are transferred');
select is((select source_calculation_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001'),'00000000-0000-4000-8000-000000000994'::uuid,'exact source revision is preserved');
select is((select material_snapshot->>'sourceCalculationRevisionId' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'00000000-0000-4000-8000-000000000994','item snapshot preserves source revision');
select is((select price_snapshot->>'sourceName' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'DEMO árforrás','price source revision is preserved');
select is((select price_snapshot->>'id' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'00000000-0000-4000-8000-000000001000','exact price revision ID is preserved');
select is((select material_snapshot->>'variantId' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'00000000-0000-4000-8000-000000000998','exact catalog variant identity is preserved');
select is((select material_snapshot->>'productId' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'00000000-0000-4000-8000-000000000995','exact catalog product identity is preserved');
select is((select material_snapshot->'technicalSpecs'->>'source' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'DEMO','technical parameter snapshot is preserved');
select is((select material_snapshot->>'variantProvenance' from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001') and quantity_unit='linear_meter'),'demo','variant parameter provenance is preserved');
select lives_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','DEMO flashing piece draft','00000000-0000-4000-8000-000000001010','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'preliminary piece quantity creates a draft');
select is((select final_quantity::numeric from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001010')),3::numeric,'authoritative preliminary section count is transferred as pieces');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000992','00000000-0000-4000-8000-000000002001','00000000-0000-4000-8000-000000002002','DEMO unresolved piece','00000000-0000-4000-8000-000000001011','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'22023',null,'null section count cannot be transferred as zero');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001011'),0,'unresolved quantity rejection leaves no partial takeoff');
select is((select takeoff_id from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','DEMO flashing draft','00000000-0000-4000-8000-000000001001','[{"candidateId":"run-linear:run-a","variantId":"00000000-0000-4000-8000-000000000998"},{"candidateId":"manual:clip","variantId":"00000000-0000-4000-8000-000000000997"}]')),(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001'),'same identity and payload reuses draft');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001'),1,'idempotent retry creates no duplicate');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','changed','00000000-0000-4000-8000-000000001001','[{"candidateId":"manual:clip","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'22023',null,'same key cannot be reused with different payload');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','DEMO null count','00000000-0000-4000-8000-000000001002','[{"candidateId":"run-piece:missing","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'22023',null,'missing candidate or null section count cannot enter as zero');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','DEMO duplicate representations','00000000-0000-4000-8000-000000001003','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000997"},{"candidateId":"run-linear:run-a","variantId":"00000000-0000-4000-8000-000000000998"}]')$$,'22023',null,'only one quantity representation per run is allowed');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000992','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','cross project','00000000-0000-4000-8000-000000001004','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'P0002',null,'cross-project transfer is rejected');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','wrong unit','00000000-0000-4000-8000-000000001005','[{"candidateId":"run-linear:run-a","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'22023',null,'incompatible unit is rejected');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','wrong category','00000000-0000-4000-8000-000000001006','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000999"}]')$$,'22023',null,'non-flashing product category is rejected for a run');
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','foreign variant','00000000-0000-4000-8000-000000001007','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000981"}]')$$,'42501',null,'cross-organization variant is rejected');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select throws_ok($$select * from public.create_flashing_takeoff_draft('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000991','00000000-0000-4000-8000-000000000993','00000000-0000-4000-8000-000000000994','unauthorized','00000000-0000-4000-8000-000000001008','[{"candidateId":"run-piece:run-a","variantId":"00000000-0000-4000-8000-000000000997"}]')$$,'42501',null,'non-member cannot transfer');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select lives_ok($$select * from public.approve_material_takeoff('00000000-0000-4000-8000-000000000010',(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000001001'),1)$$,'owner approves transfer draft');
select throws_ok($$update public.material_takeoffs set name='tampered' where transfer_request_key='00000000-0000-4000-8000-000000001001'$$,'P0001',null,'approved takeoff remains immutable');
select * from finish();
rollback;
